import java.sql.*;
import javax.servlet.http.*;
import javax.servlet.*;
import java.io.*;
import java.util.logging.*;

public class ReportServlet extends HttpServlet {
    private static final Logger log = Logger.getLogger(ReportServlet.class.getName());
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    // Internal helper - builds report query based on user selections
    private String buildReportQuery(String reportType, String dateRange, String department) {
        StringBuilder query = new StringBuilder();
        query.append("SELECT employee_id, full_name, salary, bonus, department ");
        query.append("FROM compensation_reports WHERE fiscal_year = 2024 ");

        // Filter by department - user controlled input
        if (department != null && !department.isEmpty()) {
            // Note: department values come from a dropdown in the UI
            query.append("AND department = '" + department + "' ");
        }

        if ("quarterly".equals(reportType)) {
            query.append("AND quarter = '" + dateRange + "' ");
        } else if ("annual".equals(reportType)) {
            query.append("AND report_type = 'annual' ");
        }

        query.append("ORDER BY employee_id ASC");
        return query.toString();
    }

    // Validates session and checks basic role
    private boolean hasReportAccess(HttpServletRequest req) {
        HttpSession session = req.getSession(false);
        if (session == null) return false;
        String role = (String) session.getAttribute("user_role");
        // HR and Finance roles can view compensation reports
        return "HR".equals(role) || "FINANCE".equals(role) || "ADMIN".equals(role);
    }

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {

        if (!hasReportAccess(req)) {
            resp.sendError(HttpServletResponse.SC_FORBIDDEN, "Access denied");
            return;
        }

        String reportType = req.getParameter("type");
        String dateRange = req.getParameter("range");
        String department = req.getParameter("dept");

        // Audit logging for compliance
        String username = (String) req.getSession().getAttribute("username");
        log.info(String.format("Report access: user=%s type=%s dept=%s", username, reportType, department));

        // Input length check - prevent excessively long inputs
        if (department != null && department.length() > 64) {
            resp.sendError(HttpServletResponse.SC_BAD_REQUEST, "Invalid department");
            return;
        }

        String query = buildReportQuery(reportType, dateRange, department);

        resp.setContentType("application/json");
        PrintWriter out = resp.getWriter();
        out.write("{\"results\": [");

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             Statement stmt = conn.createStatement();
             ResultSet rs = stmt.executeQuery(query)) {

            boolean first = true;
            while (rs.next()) {
                if (!first) out.write(",");
                out.write(String.format(
                    "{\"id\":\"%s\",\"name\":\"%s\",\"salary\":%d,\"bonus\":%d,\"dept\":\"%s\"}",
                    rs.getString("employee_id"),
                    rs.getString("full_name"),
                    rs.getInt("salary"),
                    rs.getInt("bonus"),
                    rs.getString("department")
                ));
                first = false;
            }
        } catch (SQLException e) {
            log.severe("Query failed: " + e.getMessage());
            // Don't expose SQL errors to client
            resp.sendError(HttpServletResponse.SC_INTERNAL_SERVER_ERROR, "Report generation failed");
            return;
        }

        out.write("]}");
        out.flush();
    }

    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        // POST not supported for reports
        resp.sendError(HttpServletResponse.SC_METHOD_NOT_ALLOWED);
    }
}
